from __future__ import annotations

import json
import os
import shutil
import threading
import uuid
from pathlib import Path

from platformdirs import user_data_path

from marul3d_api.build_engine import BuildError, export_document, export_preview
from marul3d_api.models import (
    CadDocument,
    ImportStepFeature,
    ImportStlFeature,
    sample_document,
)


class ProjectStore:
    def __init__(self, root: Path | None = None) -> None:
        configured = os.getenv("MARUL3D_DATA_DIR")
        self.root = root or (Path(configured) if configured else user_data_path("marul3D"))
        self.root.mkdir(parents=True, exist_ok=True)
        self.imports = self.root / "imports"
        self.exports = self.root / "exports"
        self.imports.mkdir(exist_ok=True)
        self.exports.mkdir(exist_ok=True)
        self.document_path = self.root / "document.json"
        self.preview_path = self.root / "preview.stl"
        self._lock = threading.RLock()
        self._undo: list[CadDocument] = []
        self._redo: list[CadDocument] = []
        self._document = self._load()
        self._ensure_preview()

    def _load(self) -> CadDocument:
        if not self.document_path.exists():
            return sample_document()
        return CadDocument.model_validate_json(self.document_path.read_text(encoding="utf-8"))

    def _write_document(self) -> None:
        temporary = self.document_path.with_suffix(".json.tmp")
        temporary.write_text(
            self._document.model_dump_json(indent=2),
            encoding="utf-8",
        )
        temporary.replace(self.document_path)

    def _ensure_preview(self) -> None:
        if self.preview_path.exists():
            return
        if any(feature.type == "import_stl" for feature in self._document.features):
            source = Path(self._document.features[0].source_path)
            if source.exists():
                shutil.copy2(source, self.preview_path)
                return
        export_preview(self._document, self.preview_path)
        self._write_document()

    def document(self) -> CadDocument:
        with self._lock:
            return self._document.model_copy(deep=True)

    def apply(self, candidate: CadDocument, *, record_history: bool = True) -> CadDocument:
        with self._lock:
            next_document = candidate.model_copy(deep=True)
            next_document.revision = self._document.revision + 1
            temporary_preview = self.root / f"preview-{uuid.uuid4().hex}.stl"
            try:
                export_preview(next_document, temporary_preview)
                if record_history:
                    self._undo.append(self._document.model_copy(deep=True))
                    self._undo = self._undo[-100:]
                    self._redo.clear()
                self._document = next_document
                temporary_preview.replace(self.preview_path)
                self._write_document()
            finally:
                temporary_preview.unlink(missing_ok=True)
            return self.document()

    def import_file(self, filename: str, content: bytes) -> CadDocument:
        suffix = Path(filename).suffix.lower()
        if suffix not in {".step", ".stp", ".stl"}:
            raise BuildError("Supported imports are .step, .stp, and .stl")
        asset_path = self.imports / f"{uuid.uuid4().hex}{suffix}"
        asset_path.write_bytes(content)
        name = Path(filename).stem or "Imported model"
        if suffix == ".stl":
            with self._lock:
                imported = CadDocument(
                    id=f"import-{uuid.uuid4().hex[:8]}",
                    name=name,
                    revision=self._document.revision + 1,
                    features=[
                        ImportStlFeature(
                            id="imported-mesh",
                            name="Imported STL reference",
                            source_path=str(asset_path),
                        )
                    ],
                )
                self._undo.append(self._document.model_copy(deep=True))
                self._redo.clear()
                self._document = imported
                shutil.copy2(asset_path, self.preview_path)
                self._write_document()
                return self.document()
        imported = CadDocument(
            id=f"import-{uuid.uuid4().hex[:8]}",
            name=name,
            features=[
                ImportStepFeature(
                    id="imported-base",
                    name="Imported STEP base",
                    source_path=str(asset_path),
                )
            ],
        )
        return self.apply(imported)

    def undo(self) -> CadDocument:
        with self._lock:
            if not self._undo:
                raise BuildError("Nothing to undo")
            candidate = self._undo.pop()
            self._redo.append(self._document.model_copy(deep=True))
            return self.apply(candidate, record_history=False)

    def redo(self) -> CadDocument:
        with self._lock:
            if not self._redo:
                raise BuildError("Nothing to redo")
            candidate = self._redo.pop()
            self._undo.append(self._document.model_copy(deep=True))
            return self.apply(candidate, record_history=False)

    def export(self, extension: str) -> Path:
        if extension not in {"step", "stl"}:
            raise BuildError("Supported exports are STEP and STL")
        destination = self.exports / f"{self._document.id}-r{self._document.revision}.{extension}"
        export_document(self._document, destination)
        return destination

    def debug_manifest(self) -> dict[str, object]:
        return json.loads(self._document.model_dump_json())

from __future__ import annotations

import ast
import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path

import cadquery as cq

from marul3d_api.models import (
    BoxFeature,
    CadDocument,
    CustomCadQueryFeature,
    CylinderFeature,
    FilletFeature,
    HolePatternFeature,
    ImportStepFeature,
    ImportStlFeature,
)


class BuildError(RuntimeError):
    pass


_FORBIDDEN_NODES = (
    ast.Import,
    ast.ImportFrom,
    ast.Global,
    ast.Nonlocal,
    ast.ClassDef,
    ast.FunctionDef,
    ast.AsyncFunctionDef,
    ast.Lambda,
    ast.With,
    ast.AsyncWith,
    ast.Try,
    ast.Raise,
)

_FORBIDDEN_NAMES = {
    "breakpoint",
    "compile",
    "eval",
    "exec",
    "globals",
    "help",
    "input",
    "locals",
    "open",
    "os",
    "pathlib",
    "socket",
    "subprocess",
    "sys",
    "type",
    "vars",
}


def validate_custom_source(source: str) -> None:
    if len(source) > 50_000:
        raise BuildError("Custom CadQuery source exceeds 50 KB")
    try:
        tree = ast.parse(source, mode="exec")
    except SyntaxError as exc:
        raise BuildError(f"Custom CadQuery syntax error: {exc.msg}") from exc

    assigns_result = False
    for node in ast.walk(tree):
        if isinstance(node, _FORBIDDEN_NODES):
            raise BuildError(f"Custom CadQuery cannot use {type(node).__name__}")
        if isinstance(node, ast.Name):
            if node.id in _FORBIDDEN_NAMES or node.id.startswith("__"):
                raise BuildError(f"Custom CadQuery cannot access {node.id!r}")
        if isinstance(node, ast.Attribute) and node.attr.startswith("_"):
            raise BuildError("Custom CadQuery cannot access private attributes")
        if isinstance(node, ast.Assign):
            assigns_result = assigns_result or any(
                isinstance(target, ast.Name) and target.id == "result" for target in node.targets
            )
    if not assigns_result:
        raise BuildError("Custom CadQuery source must assign `result`")


def _apply_boolean(
    current: cq.Workplane | None,
    tool: cq.Workplane,
    operation: str,
) -> cq.Workplane:
    if operation == "new":
        return tool
    if current is None:
        raise BuildError(f"Operation {operation!r} requires an existing solid")
    if operation == "add":
        return current.union(tool)
    if operation == "cut":
        return current.cut(tool)
    raise BuildError(f"Unsupported boolean operation: {operation}")


def _run_custom_feature(
    feature: CustomCadQueryFeature,
    current: cq.Workplane | None,
    work_dir: Path,
) -> cq.Workplane:
    validate_custom_source(feature.source)
    payload = {
        "source": feature.source,
        "parameters": {item.name: item.value for item in feature.parameters},
        "base_step": None,
        "output_step": str(work_dir / f"{feature.id}-result.step"),
    }
    if current is not None:
        base_path = work_dir / f"{feature.id}-base.step"
        cq.exporters.export(current, str(base_path))
        payload["base_step"] = str(base_path)

    payload_path = work_dir / f"{feature.id}-payload.json"
    payload_path.write_text(json.dumps(payload), encoding="utf-8")
    env = os.environ.copy()
    env["PYTHONNOUSERSITE"] = "1"
    try:
        completed = subprocess.run(
            [sys.executable, "-m", "marul3d_api.custom_worker", str(payload_path)],
            cwd=work_dir,
            env=env,
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise BuildError("Custom CadQuery execution exceeded 15 seconds") from exc
    if completed.returncode != 0:
        detail = completed.stderr.strip().splitlines()[-1] if completed.stderr.strip() else "failed"
        raise BuildError(f"Custom CadQuery execution failed: {detail}")
    return cq.importers.importStep(payload["output_step"])


def build_document(document: CadDocument) -> cq.Workplane:
    current: cq.Workplane | None = None
    with tempfile.TemporaryDirectory(prefix="marul3d-build-") as temporary:
        work_dir = Path(temporary)
        for feature in document.features:
            if not feature.enabled:
                continue
            try:
                if isinstance(feature, BoxFeature):
                    tool = cq.Workplane(
                        "XY", origin=(feature.x, feature.y, feature.z)
                    ).box(feature.width, feature.depth, feature.height, centered=(True, True, False))
                    current = _apply_boolean(current, tool, feature.operation)
                elif isinstance(feature, CylinderFeature):
                    tool = cq.Workplane(
                        "XY", origin=(feature.x, feature.y, feature.z)
                    ).circle(feature.radius).extrude(feature.height)
                    current = _apply_boolean(current, tool, feature.operation)
                elif isinstance(feature, HolePatternFeature):
                    if current is None:
                        raise BuildError("A hole pattern requires an existing solid")
                    points = [(point.x, point.y) for point in feature.points]
                    workplane = current.faces(">Z").workplane().pushPoints(points)
                    current = (
                        workplane.hole(feature.diameter, feature.depth)
                        if feature.depth is not None
                        else workplane.hole(feature.diameter)
                    )
                elif isinstance(feature, FilletFeature):
                    if current is None:
                        raise BuildError("A fillet requires an existing solid")
                    edges = current.edges("|Z") if feature.selector == "vertical" else current.edges()
                    current = edges.fillet(feature.radius)
                elif isinstance(feature, ImportStepFeature):
                    current = cq.importers.importStep(feature.source_path)
                elif isinstance(feature, ImportStlFeature):
                    if len(document.features) > 1:
                        raise BuildError("STL reference meshes cannot receive B-rep features")
                elif isinstance(feature, CustomCadQueryFeature):
                    current = _run_custom_feature(feature, current, work_dir)
            except BuildError:
                raise
            except Exception as exc:
                raise BuildError(f"Feature {feature.name!r} failed: {exc}") from exc

        if current is None:
            raise BuildError("The document does not contain a buildable solid")
        try:
            if not current.val().isValid():
                raise BuildError("OpenCascade reported an invalid result")
        except AttributeError as exc:
            raise BuildError("The document result is not a valid CadQuery shape") from exc
        return current


def export_preview(document: CadDocument, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    shape = build_document(document)
    cq.exporters.export(
        shape,
        str(destination),
        exportType="STL",
        tolerance=0.08,
        angularTolerance=0.12,
    )


def export_document(document: CadDocument, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    shape = build_document(document)
    cq.exporters.export(shape, str(destination))

from __future__ import annotations

from functools import lru_cache
from pathlib import Path

from fastapi import Depends, FastAPI, File, HTTPException, UploadFile
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse

from marul3d_api import __version__
from marul3d_api.build_engine import BuildError
from marul3d_api.credentials import CredentialStore
from marul3d_api.models import (
    BuildResponse,
    CadDocument,
    CredentialRequest,
    GenerateRequest,
    ProviderStatus,
)
from marul3d_api.project_store import ProjectStore
from marul3d_api.providers import OpenAIProvider

app = FastAPI(
    title="marul3D local API",
    version=__version__,
    docs_url="/api/docs",
    openapi_url="/api/openapi.json",
)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:5173", "http://127.0.0.1:5173"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "PUT"],
    allow_headers=["Content-Type"],
)


@lru_cache(maxsize=1)
def get_store() -> ProjectStore:
    return ProjectStore()


@lru_cache(maxsize=1)
def get_credentials() -> CredentialStore:
    return CredentialStore()


def _build_response(document: CadDocument, summary: str | None = None) -> BuildResponse:
    return BuildResponse(
        document=document,
        preview_revision=document.revision,
        summary=summary,
    )


@app.get("/api/health")
def health() -> dict[str, str]:
    return {"status": "ok", "version": __version__}


@app.get("/api/document", response_model=BuildResponse)
def read_document(store: ProjectStore = Depends(get_store)) -> BuildResponse:
    return _build_response(store.document())


@app.put("/api/document", response_model=BuildResponse)
def update_document(
    document: CadDocument,
    store: ProjectStore = Depends(get_store),
) -> BuildResponse:
    try:
        return _build_response(store.apply(document))
    except BuildError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc


@app.get("/api/preview.stl", response_class=FileResponse)
def preview(store: ProjectStore = Depends(get_store)) -> FileResponse:
    return FileResponse(
        store.preview_path,
        media_type="model/stl",
        filename="marul3d-preview.stl",
        headers={"Cache-Control": "no-store"},
    )


@app.post("/api/generate", response_model=BuildResponse)
def generate(
    request: GenerateRequest,
    store: ProjectStore = Depends(get_store),
    credentials: CredentialStore = Depends(get_credentials),
) -> BuildResponse:
    api_key, _ = credentials.get(request.provider)
    if not api_key:
        raise HTTPException(status_code=409, detail="Add an OpenAI API key in Settings first")
    try:
        provider = OpenAIProvider(api_key)
        proposal = provider.propose(request.prompt, store.document(), request.model)
        return _build_response(store.apply(proposal.document), proposal.summary)
    except BuildError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    except Exception as exc:
        raise HTTPException(status_code=502, detail=str(exc)) from exc


@app.get("/api/settings/providers/openai", response_model=ProviderStatus)
def provider_status(
    credentials: CredentialStore = Depends(get_credentials),
) -> ProviderStatus:
    value, storage = credentials.get("openai")
    return ProviderStatus(
        provider="openai",
        configured=bool(value),
        storage=storage,
    )


@app.post("/api/settings/api-key", response_model=ProviderStatus)
def save_api_key(
    request: CredentialRequest,
    credentials: CredentialStore = Depends(get_credentials),
) -> ProviderStatus:
    try:
        credentials.set(request.provider, request.api_key)
    except RuntimeError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc
    return ProviderStatus(provider=request.provider, configured=True, storage="keychain")


@app.post("/api/import", response_model=BuildResponse)
async def import_model(
    file: UploadFile = File(...),
    store: ProjectStore = Depends(get_store),
) -> BuildResponse:
    content = await file.read()
    if not content:
        raise HTTPException(status_code=400, detail="The selected file is empty")
    if len(content) > 100 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="Imports are limited to 100 MB")
    try:
        document = store.import_file(file.filename or "model.step", content)
        return _build_response(document, f"Imported {Path(file.filename or 'model').name}")
    except BuildError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc


@app.post("/api/history/undo", response_model=BuildResponse)
def undo(store: ProjectStore = Depends(get_store)) -> BuildResponse:
    try:
        return _build_response(store.undo())
    except BuildError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc


@app.post("/api/history/redo", response_model=BuildResponse)
def redo(store: ProjectStore = Depends(get_store)) -> BuildResponse:
    try:
        return _build_response(store.redo())
    except BuildError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc


@app.get("/api/export/{extension}", response_class=FileResponse)
def export_model(
    extension: str,
    store: ProjectStore = Depends(get_store),
) -> FileResponse:
    try:
        path = store.export(extension.lower())
    except BuildError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    media_type = "model/stl" if extension.lower() == "stl" else "model/step"
    return FileResponse(path, media_type=media_type, filename=path.name)

