import {
  Box,
  CircleDot,
  Code2,
  Cylinder,
  FileBox,
  FolderOpen,
  Radius,
} from "lucide-react";
import type { Feature } from "../types";

const icons = {
  box: Box,
  cylinder: Cylinder,
  hole_pattern: CircleDot,
  fillet: Radius,
  import_step: FileBox,
  import_stl: FileBox,
  custom_cadquery: Code2,
};

export function FeatureTree({
  name,
  features,
  selectedId,
  onSelect,
}: {
  name: string;
  features: Feature[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  return (
    <aside className="explorer-panel">
      <div className="panel-heading">EXPLORER</div>
      <div className="project-heading">
        <FolderOpen size={15} />
        <span>{name}</span>
      </div>
      <div className="tree-label">FEATURE HISTORY</div>
      <div className="feature-tree">
        {features.map((feature, index) => {
          const Icon = icons[feature.type];
          return (
            <button
              type="button"
              className={`feature-row ${selectedId === feature.id ? "selected" : ""}`}
              key={feature.id}
              onClick={() => onSelect(feature.id)}
            >
              <span className="feature-index">{index + 1}</span>
              <Icon size={15} strokeWidth={1.8} />
              <span className="feature-name">{feature.name}</span>
              {!feature.enabled && <span className="feature-disabled">off</span>}
            </button>
          );
        })}
      </div>
      <div className="tree-footer">{features.length} parametric features</div>
    </aside>
  );
}

import { KeyRound, X } from "lucide-react";
import { FormEvent, useState } from "react";

export function SettingsDialog({
  configured,
  onClose,
  onSave,
}: {
  configured: boolean;
  onClose: () => void;
  onSave: (apiKey: string) => Promise<void>;
}) {
  const [apiKey, setApiKey] = useState("");
  const [saving, setSaving] = useState(false);

  async function submit(event: FormEvent) {
    event.preventDefault();
    setSaving(true);
    try {
      await onSave(apiKey);
      onClose();
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="dialog-backdrop" role="presentation" onMouseDown={onClose}>
      <section className="settings-dialog" role="dialog" aria-modal="true" onMouseDown={(e) => e.stopPropagation()}>
        <header>
          <div>
            <span className="dialog-kicker">MODEL PROVIDERS</span>
            <h2>OpenAI connection</h2>
          </div>
          <button className="icon-button" type="button" onClick={onClose} aria-label="Close settings">
            <X size={18} />
          </button>
        </header>
        <form onSubmit={submit}>
          <label className="key-field">
            <span>API key</span>
            <div>
              <KeyRound size={16} />
              <input
                autoFocus
                type="password"
                autoComplete="off"
                placeholder={configured ? "Replace the saved key" : "sk-…"}
                value={apiKey}
                onChange={(event) => setApiKey(event.target.value)}
              />
            </div>
          </label>
          <p>
            Saved by the local Python service in macOS Keychain. The key is never returned to this browser or
            written to the project.
          </p>
          <footer>
            <span className={`connection-state ${configured ? "connected" : ""}`}>
              {configured ? "Configured in Keychain" : "Not configured"}
            </span>
            <button className="primary-button" disabled={apiKey.length < 8 || saving} type="submit">
              {saving ? "Saving…" : "Save securely"}
            </button>
          </footer>
        </form>
      </section>
    </div>
  );
}

import { SlidersHorizontal } from "lucide-react";
import type { Feature } from "../types";

type EditableNumber = { key: string; label: string; value: number; unit?: string };

function numericFields(feature: Feature): EditableNumber[] {
  switch (feature.type) {
    case "box":
      return [
        { key: "width", label: "Width", value: feature.width, unit: "mm" },
        { key: "depth", label: "Depth", value: feature.depth, unit: "mm" },
        { key: "height", label: "Height", value: feature.height, unit: "mm" },
      ];
    case "cylinder":
      return [
        { key: "radius", label: "Radius", value: feature.radius, unit: "mm" },
        { key: "height", label: "Height", value: feature.height, unit: "mm" },
      ];
    case "hole_pattern":
      return [{ key: "diameter", label: "Diameter", value: feature.diameter, unit: "mm" }];
    case "fillet":
      return [{ key: "radius", label: "Radius", value: feature.radius, unit: "mm" }];
    case "custom_cadquery":
      return feature.parameters.map((parameter, index) => ({
        key: `parameters.${index}`,
        label: parameter.name,
        value: parameter.value,
        unit: parameter.unit,
      }));
    default:
      return [];
  }
}

export function Inspector({
  feature,
  disabled,
  onNumericChange,
}: {
  feature: Feature | null;
  disabled: boolean;
  onNumericChange: (key: string, value: number) => void;
}) {
  return (
    <aside className="inspector-panel">
      <div className="panel-heading inspector-title">
        <span>PROPERTIES</span>
        <SlidersHorizontal size={14} />
      </div>
      {!feature ? (
        <div className="empty-inspector">Select a feature to edit its parameters.</div>
      ) : (
        <div className="inspector-body">
          <div className="feature-kind">{feature.type.replaceAll("_", " ")}</div>
          <h2>{feature.name}</h2>
          <div className="property-section-title">Parameters</div>
          {numericFields(feature).map((field) => (
            <label className="property-row" key={field.key}>
              <span>{field.label}</span>
              <span className="number-input-wrap">
                <input
                  aria-label={field.label}
                  type="number"
                  min="0.001"
                  step="0.5"
                  value={field.value}
                  disabled={disabled}
                  onChange={(event) => onNumericChange(field.key, Number(event.target.value))}
                />
                {field.unit && <em>{field.unit}</em>}
              </span>
            </label>
          ))}
          {feature.type === "hole_pattern" && (
            <div className="property-note">{feature.points.length} hole locations</div>
          )}
          {feature.type === "custom_cadquery" && (
            <details className="source-details">
              <summary>CadQuery source</summary>
              <pre>{feature.source}</pre>
            </details>
          )}
          {numericFields(feature).length === 0 && feature.type !== "custom_cadquery" && (
            <div className="property-note">This imported base has no native parameters.</div>
          )}
        </div>
      )}
    </aside>
  );
}

import { Bounds, Grid, OrbitControls, PerspectiveCamera } from "@react-three/drei";
import { Canvas, useLoader } from "@react-three/fiber";
import { Suspense } from "react";
import { STLLoader } from "three/examples/jsm/loaders/STLLoader.js";

function PartMesh({ revision }: { revision: number }) {
  const geometry = useLoader(STLLoader, `/api/preview.stl?revision=${revision}`);
  geometry.computeVertexNormals();
  return (
    <Bounds fit clip observe margin={1.35}>
      <mesh geometry={geometry} rotation={[-Math.PI / 2, 0, 0]} castShadow receiveShadow>
        <meshStandardMaterial color="#b8df75" roughness={0.5} metalness={0.08} />
      </mesh>
    </Bounds>
  );
}

function LoadingPart() {
  return (
    <mesh>
      <boxGeometry args={[20, 6, 12]} />
      <meshStandardMaterial color="#58614f" wireframe />
    </mesh>
  );
}

export function CadViewport({ revision }: { revision: number }) {
  return (
    <div className="viewport-canvas" data-testid="cad-viewport">
      <Canvas shadows dpr={[1, 2]} gl={{ antialias: true }}>
        <color attach="background" args={["#151815"]} />
        <fog attach="fog" args={["#151815", 100, 360]} />
        <PerspectiveCamera makeDefault position={[68, 54, 72]} fov={38} />
        <ambientLight intensity={1.1} />
        <directionalLight
          castShadow
          intensity={2.4}
          position={[45, 70, 38]}
          shadow-mapSize={[2048, 2048]}
        />
        <directionalLight intensity={0.8} position={[-35, 15, -30]} color="#b7d0ff" />
        <Suspense fallback={<LoadingPart />}>
          <PartMesh revision={revision} />
        </Suspense>
        <Grid
          infiniteGrid
          fadeDistance={180}
          fadeStrength={3}
          cellSize={5}
          sectionSize={25}
          cellColor="#2f352d"
          sectionColor="#44513c"
          position={[0, -0.08, 0]}
        />
        <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
      </Canvas>
      <div className="view-cube" aria-hidden="true">
        <span>TOP</span>
      </div>
      <div className="viewport-hint">Orbit · left drag&nbsp;&nbsp; Pan · right drag&nbsp;&nbsp; Zoom · scroll</div>
    </div>
  );
}

